<?php header('Content-Type: application/json');try{$c=require __DIR__.'/config.php';$p=new PDO("mysql:host={$c['db_host']};dbname={$c['db_name']};charset=utf8mb4",$c['db_user'],$c['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$products=$p->query("SELECT id,name,category,price,image_url,image_url AS image,icon,details FROM products WHERE active=1 ORDER BY featured DESC,id DESC")->fetchAll(PDO::FETCH_ASSOC);$categories=$p->query("SELECT name FROM categories WHERE active=1 ORDER BY sort_order,id")->fetchAll(PDO::FETCH_COLUMN);echo json_encode(['products'=>$products,'categories'=>$categories]);}catch(Throwable $e){echo json_encode(['products'=>[],'categories'=>[]]);}